#[test]
fn calc_ozone_stress_matches_fortran_bitwise() {
    for (row, &(ivt, use_data, input, expected)) in FORTRAN_CASES.iter().enumerate() {
        let x = input.map(f64::from_bits);
        let class = usize::try_from(ivt).unwrap();
        let parameters = OzoneParameters {
            vegetation_type: ivt,
            evergreen: EVERGREEN[class],
            leaf_longevity_years: LEAF_LONG[class],
            stomatal_resistance_factor: x[11],
            use_data,
        };
        let concentration = parameters.effective_concentration_ppbv(x[0]);
        let mut uptake = x[8];
        let (vcmax, conductance) = ozone_stress(
            parameters,
            OzoneUptakeInput {
                concentration_ppbv: concentration,
                surface_pressure_pa: x[1],
                potential_temperature_k: x[2],
                aerodynamic_resistance_s_m: x[3],
                stomatal_resistance_s_m: x[4],
                boundary_resistance_s_m: x[5],
                leaf_area_index: x[6],
                previous_leaf_area_index: x[7],
                absorbed_solar_w_m2: x[9],
                time_step_seconds: x[10],
            },
            &mut uptake,
        );
        let got = [vcmax, conductance, concentration, uptake].map(f64::to_bits);
        assert_eq!(got, expected, "row {row} (ivt {ivt})");
    }
}

/// 收敛后的一对调用：两次都用进来的 `lai_old`，之后才 `lai_old = lai`；没有数据时 `forc_ozone` 写成 100。
#[test]
fn canopy_ozone_stress_updates_both_leaves_then_lai_old() {
    let parameters = OzoneParameters {
        vegetation_type: 13,
        evergreen: false,
        leaf_longevity_years: LEAF_LONG[13],
        stomatal_resistance_factor: 1.51,
        use_data: false,
    };
    let mut state = OzoneState {
        previous_leaf_area_index: 2.0,
        sunlit_uptake_mmol_m2: 3.0,
        shaded_uptake_mmol_m2: 1.0,
        sunlit_photosynthesis_factor: 1.0,
        shaded_photosynthesis_factor: 1.0,
        sunlit_conductance_factor: 1.0,
        shaded_conductance_factor: 1.0,
        concentration_ppbv: crate::MISSING,
    };
    let (sun, sha) = canopy_ozone_stress(
        parameters, &mut state, 1.0e5, 290.0, 50.0, 200.0, 800.0, 20.0, 2.5, 300.0, 1800.0,
    );
    assert_eq!(state.concentration_ppbv, CONSTANT_OZONE_PPBV);
    assert_eq!(state.previous_leaf_area_index, 2.5);
    // 两片叶各自独立推进：同样以 `lai_old = 2` 算衰减，不受先算的阳叶影响。
    let mut sunlit = 3.0;
    let mut shaded = 1.0;
    let one = |rs: f64, uptake: &mut f64| {
        ozone_stress(
            parameters,
            OzoneUptakeInput {
                concentration_ppbv: 100.0,
                surface_pressure_pa: 1.0e5,
                potential_temperature_k: 290.0,
                aerodynamic_resistance_s_m: 50.0,
                stomatal_resistance_s_m: rs,
                boundary_resistance_s_m: 20.0,
                leaf_area_index: 2.5,
                previous_leaf_area_index: 2.0,
                absorbed_solar_w_m2: 300.0,
                time_step_seconds: 1800.0,
            },
            uptake,
        )
    };
    let sunlit_factors = one(200.0, &mut sunlit);
    let shaded_factors = one(800.0, &mut shaded);
    assert_eq!(state.sunlit_uptake_mmol_m2, sunlit);
    assert_eq!(state.shaded_uptake_mmol_m2, shaded);
    assert_eq!((sun, state.sunlit_conductance_factor), sunlit_factors);
    assert_eq!((sha, state.shaded_conductance_factor), shaded_factors);
    assert!(sun < 1.0 && sha < 1.0);
}

/// 有数据时 `forc_ozone` 原样使用；裸地（`ivt = 0`）有吸收量时两个因子是 1（upstream-bugs 第 71 条）。
#[test]
fn data_concentration_and_bare_ground_factors() {
    let parameters = OzoneParameters {
        vegetation_type: 0,
        evergreen: false,
        leaf_longevity_years: 0.0,
        stomatal_resistance_factor: 1.51,
        use_data: true,
    };
    assert_eq!(parameters.effective_concentration_ppbv(37.5), 37.5);
    let mut uptake = 5.0;
    let factors = ozone_stress(
        parameters,
        OzoneUptakeInput {
            concentration_ppbv: 37.5,
            surface_pressure_pa: 1.0e5,
            potential_temperature_k: 290.0,
            aerodynamic_resistance_s_m: 50.0,
            stomatal_resistance_s_m: 100.0,
            boundary_resistance_s_m: 20.0,
            leaf_area_index: 1.0,
            previous_leaf_area_index: 1.0,
            absorbed_solar_w_m2: 0.0,
            time_step_seconds: 1800.0,
        },
        &mut uptake,
    );
    assert_eq!(uptake, 5.0);
    assert_eq!(factors, (1.0, 1.0));
}
